fn putd(o:[*]u8,p:usize,x:f64)void{const b=@as(u64,@bitCast(x));for(0..8)|k|o[p+k]=@truncate(b>>(8*k));}
export fn fuzzy_set_operations(v:[*]const i64,n:usize,o:[*]u8,cap:usize)i64{if(n<8)return -1;const op=v[0];const m=v[1];if(op<0 or op>8 or m<1 or m>8 or n!=@as(usize,@intCast(5+3*m)))return -1;for(5..n)|i|{if(v[i]<0 or v[i]>1000)return -1;}const l=v[2];const p=v[3];const r=v[4];if(op==0){if(l<0 or p<l or r<p or r>1000)return -1;for(0..@intCast(m))|i|{if(v[5+@as(usize,@intCast(m))+i]!=0 or v[5+2*@as(usize,@intCast(m))+i]!=0)return -1;}}else{if(l!=0 or p!=0 or r!=0)return -1;for(0..@intCast(m))|i|{if(v[5+i]!=0)return -1;}}if(cap<@as(usize,@intCast(m))*8)return -2;for(0..@intCast(m))|i|{var z:f64=0;if(op==0){const x=@as(f64,@floatFromInt(v[5+i]))/1000.0;const a=@as(f64,@floatFromInt(l))/1000.0;const b=@as(f64,@floatFromInt(p))/1000.0;const c=@as(f64,@floatFromInt(r))/1000.0;const u=if(b>a)(x-a)/(b-a) else if(x<b) 0.0 else 1.0;const w=if(c>b)(c-x)/(c-b) else if(x>c) 0.0 else 1.0;z=@max(0.0,@min(1.0,@min(u,w)));}else{const a=@as(f64,@floatFromInt(v[5+@as(usize,@intCast(m))+i]))/1000.0;const b=@as(f64,@floatFromInt(v[5+2*@as(usize,@intCast(m))+i]))/1000.0;z=switch(op){1=>@max(a,b),2=>@min(a,b),3=>1.0-a,4=>@min(a,1.0-b),5=>a+b-a*b,6=>a*b,7=>@min(1.0,a+b),else=>@max(0.0,a+b-1.0)};}putd(o,i*8,z);}return m*8;}
